WITH flattened AS (SELECT id, plan, effective_from, currency, EXPLODE(tier_prices) AS tier_value FROM price_tiers) SELECT plan, CASE WHEN tier_value >= 74 THEN 'LARGE' ELSE 'SMALL' END AS tier_value_tier, DATE_TRUNC('QUARTER', effective_from) AS quarter_start, COUNT_IF(plan = 'basic') AS basic_events, SUM(tier_value) AS total_tier_value, SUM(tier_value) FILTER (WHERE currency = 'EUR') AS eur_total_tier_value, GROUPING(plan) AS gid FROM flattened GROUP BY ROLLUP (plan, CASE WHEN tier_value >= 74 THEN 'LARGE' ELSE 'SMALL' END, DATE_TRUNC('QUARTER', effective_from)) HAVING basic_events < 1000;
